<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- getItemIconHTML from the rocket snapshot */
  import { onMount } from 'svelte';
  import { rocket } from '../../stores/rocket.svelte.ts';
  import { game } from '../../../gameManager.js';
  import { logMessage } from '../../ui/modals.ts';
  import { uiText } from '../../ui/i18n.ts';
  import {
    setRocketContractOpen,
    setRocketContractClose,
    closeRocketContractSelectModal,
  } from '../../bridge/rocketContractModalBridge.js';
  import type { RocketContractModalSnapshot } from '../../bus/snapshots.js';

  let visible = $state(false);
  let snap = $state<RocketContractModalSnapshot | null>(null);

  function open(snapshot: RocketContractModalSnapshot): void {
    snap = snapshot;
    visible = true;
  }

  function close(): void {
    visible = false;
    snap = null;
  }

  function handleConfirm(): void {
    if (!snap || !game) return;
    if (typeof game.handleRocketConfirmContractSelection !== 'function') return;
    if (snap.requestedType === 'item') {
      const ok = game.handleRocketConfirmContractSelection(snap.contractId, []);
      if (ok) close();
      return;
    }
    const checked = Array.from(
      document.querySelectorAll<HTMLInputElement>('#rocketContractSelectList .rocket-contract-choice:checked'),
    )
      .map((el) => Number(el.value))
      .filter(Number.isInteger);
    if (checked.length !== snap.needed) {
      logMessage(uiText('modal.invalidSelection', null, { needed: snap.needed }, game));
      return;
    }
    const ok = game.handleRocketConfirmContractSelection(snap.contractId, checked);
    if (ok) close();
  }

  onMount(() => {
    setRocketContractOpen(open);
    setRocketContractClose(close);
    return () => {
      setRocketContractOpen(() => {});
      setRocketContractClose(() => {});
    };
  });
</script>

{#if visible && snap}
  <div
    id="rocketContractSelectOverlay"
    class="stats-modal js-modal-overlay show"
    role="dialog"
    aria-modal="true"
    tabindex="-1"
    onclick={(e) => { if (e.target === e.currentTarget) closeRocketContractSelectModal(); }}
    onkeydown={(e) => { if (e.key === 'Escape') closeRocketContractSelectModal(); }}
  >
    <div
      class="stats-content js-modal-content"
      style="max-width: 760px; width:min(92vw, 760px);"
      data-action="stopPropagation"
      data-action-stop
    >
      <div class="stats-header">
        <h2>{snap.title}</h2>
        <button class="stats-close js-close-modal" type="button" data-action="closeRocketContractSelectModal">&times;</button>
      </div>
      <div class="tr-text-body">{snap.requirementText}</div>
      <div id="rocketContractSelectList" style="margin-top: 8px;">
        {#if snap.item}
          <div class="shop-item" class:not-affordable={!snap.item.ok} style="margin-top:10px;">
            <div style="display:flex; align-items:center; gap:10px;">
              <div style="min-width:32px; display:flex; align-items:center; justify-content:center;">
                {@html snap.item.iconHtml}
              </div>
              <div class="tr-text-title">{snap.item.displayName}</div>
            </div>
            <div class="tr-text-value">{snap.item.ownedText}</div>
            {#if !snap.item.ok}
              <div class="tr-text-status tr-text-status--danger" style="margin-top:6px;">{snap.item.insufficientText}</div>
            {/if}
          </div>
        {:else if snap.pokemon.length > 0}
          {#each snap.pokemon as opt (opt.storageIndex)}
            <label class="shop-item rocket-contract-select-card" style="display:block; cursor:pointer; margin-top:8px;">
              <div class="rocket-contract-select-row">
                <input type="checkbox" class="rocket-contract-choice" value={String(opt.storageIndex)} />
                <img
                  src={opt.spriteUrl}
                  alt={opt.displayName}
                  style="width:44px; height:44px; image-rendering:pixelated; object-fit:contain;"
                />
                <div class="rocket-contract-select-meta">
                  <div class="tr-text-title">{opt.displayName}</div>
                  <div class="tr-text-body">{opt.metaLine}</div>
                </div>
              </div>
            </label>
          {/each}
        {:else}
          <div class="tr-text-status tr-text-status--danger" style="margin-top:10px;">{snap.noPokemonText}</div>
        {/if}
      </div>
      <div style="display:flex; gap:8px; justify-content:flex-end; margin-top: 12px;">
        <button class="shop-buy-btn" type="button" data-action="closeRocketContractSelectModal">{snap.cancelLabel}</button>
        <button class="shop-buy-btn" type="button" id="rocketContractConfirmBtn" onclick={handleConfirm}>{snap.confirmLabel}</button>
      </div>
    </div>
  </div>
{/if}
